95	            dataChange,
96	            deletionVectorDescriptor,
97	            tagMapValue, // tags
98	            baseRowId,
99	            defaultRowCommitVersion,
100	            dataFileStatus.getStatistics());
101	
102	    return new AddFile(row);
103	  }
