125	    fieldMap.put(FULL_SCHEMA.indexOf("size"), size);
126	    fieldMap.put(FULL_SCHEMA.indexOf("modificationTime"), modificationTime);
127	    fieldMap.put(FULL_SCHEMA.indexOf("dataChange"), dataChange);
128	    tags.ifPresent(tag -> fieldMap.put(FULL_SCHEMA.indexOf("tags"), tag));
129	    baseRowId.ifPresent(id -> fieldMap.put(FULL_SCHEMA.indexOf("baseRowId"), id));
