package io.delta.spark.internal.v2.read;

import io.delta.kernel.internal.actions.AddFile;
import org.apache.spark.sql.delta.commands.cdc.CDCReader;

/**
 * Wraps an {@link AddFile} with Change Data Capture (CDC) metadata, namely the change type and the
 * commit timestamp of the version that produced the file.
 *
 * <p>Instances are created via the {@link #fromAddFile(AddFile, long)} static factory method.
 */
public class CDCDataFile {
  private final AddFile addFile;
  private final String changeType;
  private final long commitTimestamp;

  private CDCDataFile(AddFile addFile, String changeType, long commitTimestamp) {
    this.addFile = addFile;
    this.changeType = changeType;
    this.commitTimestamp = commitTimestamp;
  }

  /**
   * Creates a {@link CDCDataFile} wrapping the given {@link AddFile} with the CDC insert change
   * type (see {@link CDCReader#CDC_TYPE_INSERT()}) and the provided commit timestamp.
   */
  public static CDCDataFile fromAddFile(AddFile addFile, long commitTimestamp) {
    return new CDCDataFile(addFile, CDCReader.CDC_TYPE_INSERT(), commitTimestamp);
  }

  public AddFile getAddFile() {
    return addFile;
  }

  public String getChangeType() {
    return changeType;
  }

  public long getCommitTimestamp() {
    return commitTimestamp;
  }

  public long getFileSize() {
    return addFile.getSize();
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append("CDCDataFile{");
    sb.append("addFile=").append(addFile);
    sb.append(", changeType='").append(changeType).append('\'');
    sb.append(", commitTimestamp=").append(commitTimestamp);
    sb.append('}');
    return sb.toString();
  }
}
